export const findFeature = (slug) => CATALOGUE.find((f) => f.slug === slug) || null;
export const byFamily = (family) => CATALOGUE.filter((f) => f.family === family);
export const byStatus = (status) => CATALOGUE.filter((f) => f.status === status);
